import json

with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def build_lookup(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        result[name] = {}
        for fw in proj.get('frameworks', []):
            result[name][fw['framework']] = {}
            for pkg in fw.get('topLevelPackages', []):
                result[name][fw['framework']][pkg['id']] = pkg['resolvedVersion']
    return result

b = build_lookup(baseline)
a = build_lookup(after)

print('=== CHANGES ===')
changes_list = []
unchanged_list = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    for fw in sorted(set(list(b.get(proj,{}).keys()) + list(a.get(proj,{}).keys()))):
        bp = b.get(proj,{}).get(fw,{})
        ap = a.get(proj,{}).get(fw,{})
        for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
            bv = bp.get(pkg, 'N/A')
            av = ap.get(pkg, 'N/A')
            if bv != av:
                changes_list.append((proj, fw, pkg, bv, av))
            else:
